import {cafeGuest,cafePlateStatus} from './care-art.js';
import {iconArt} from './premium-art.js';
import {FOOD} from './refine-core.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const FOOD_GROUPS=[{id:'base',icon:'🍞',name:'Breads'},{id:'protein',icon:'🥩',name:'Proteins'},{id:'veg',icon:'🥬',name:'Veggies'},{id:'topping',icon:'🧀',name:'Toppings'},{id:'sauce',icon:'🧪',name:'Sauces'},{id:'extra',icon:'🍨',name:'Treats'},{id:'fruit',icon:'🍓',name:'Fruit'}];
export function cafePanelHTML(m,learn=false){
 const o=m.orders[m.orderIndex||0],category=FOOD_GROUPS.find(g=>g.id===m.foodCategory)||FOOD_GROUPS[0];
 const recipe=o?o.recipe.items:[],foods=m.ingredients.filter(f=>f.group===category.id),recipeItems=learn?[...new Set(recipe)]:recipe;
 return `<div class="chef-orders" aria-label="Monster customers">${m.orders.map((order,j)=>`<button data-order="${j}" class="${j===(m.orderIndex||0)?'selected':''}" aria-pressed="${j===(m.orderIndex||0)}"><span>${iconArt('avatar',['👾','🐲','👽','🐙'][order.id%4])}</span><strong>${cafeGuest(order)} · ${esc(order.recipe.name)}</strong><small>${order.sequence?'STACK IN ORDER':'ANY ORDER'}</small><i role="progressbar" aria-label="${cafeGuest(order)} patience" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(Math.max(0,100*(1-(m.clock-order.at)/order.patience)))}" style="--patience:${Math.max(0,100*(1-(m.clock-order.at)/order.patience))}%"></i></button>`).join('')}</div>
 <div class="chef-recipe"><div><strong>${esc(o?.recipe.name||'Choose a customer')}</strong><small>${o?.sequence?'Place ingredients in the order shown':'Match every ingredient · no extras'}</small></div><div class="chef-recipe-pieces">${recipeItems.map((id,j)=>`<span><b>${iconArt('food',id)}</b><span>${m.plate.filter(x=>x===id).length>=recipe.filter(x=>x===id).length?'✓ ':''}${learn?recipe.filter(x=>x===id).length+' × ':o?.sequence?(j+1)+'. ':''}${esc(FOOD(id).name)}</span></span>`).join('')}</div></div>
 <nav class="chef-categories" aria-label="Ingredient categories">${FOOD_GROUPS.map(g=>{const n=m.ingredients.filter(f=>f.group===g.id).length;return `<button data-category="${g.id}" aria-pressed="${g.id===category.id}" ${n?'':'disabled'}><b>${g.icon}</b><span>${g.name}</span><small>${n}</small></button>`;}).join('')}</nav>
 <div class="chef-pantry" aria-label="${category.name} ingredients">${foods.map(f=>{const n=m.plate.filter(id=>id===f.id).length,needed=m.difficulty<=2&&recipe.includes(f.id);return `<button data-food="${f.id}" class="${needed?'needed':''}" aria-label="Add ${esc(f.name)}" title="${esc(f.name)}"><span>${iconArt('food',f.id)}</span><strong>${esc(f.name)}</strong>${n?`<i>${n} on plate</i>`:needed?'<i>Recipe ingredient</i>':''}</button>`;}).join('')}</div>`;
}
export function cafePlateHTML(m,name){return `<section class="chef-plate" id="chefPlate" aria-label="Ingredient plate"><header><div><strong>${esc(name)}’s plate</strong><small>Drop food here · tap an ingredient to remove it</small></div><button data-undo class="btn secondary" aria-label="Remove last ingredient">↶ UNDO</button><button data-clear class="btn secondary">CLEAR</button></header><div class="chef-plate-items">${Array.from({length:7},(_,j)=>{let f=FOOD(m.plate[j]);return f?`<button data-remove-food="${j}" aria-label="Remove ${esc(f.name)}"><b>${iconArt('food',f.id)}</b><small>${esc(f.name)}</small><i>×</i></button>`:'<span class="empty-ingredient" aria-hidden="true">＋</span>';}).join('')}</div><p class="chef-status" role="status">${cafePlateStatus(m)}</p><footer><span><b>STREAK ${m.combo}</b><small>NEXT ORDER ×${m.cafeMultiplier().toFixed(2)}</small></span><button data-serve class="btn primary" ${m.plate.length?'':'disabled'}>SERVE ORDER ✓</button></footer></section>`;}
